<script setup lang="ts">
import{ref,onMounted}from'vue';import{request,post}from'../api/client';import{ElMessageBox}from'element-plus'
interface Plugin{manifest:{id:string;name:string;version:string;contractVersion:number;endpoint?:string;capabilities:string[]};enabled:boolean;builtin:boolean;revision:number}
const items=ref<Plugin[]>([]),text=ref(''),busy=ref(false),error=ref('')
async function load(){try{items.value=await request('/plugins')}catch(e){error.value=e instanceof Error?e.message:'插件读取失败'}}
async function add(){busy.value=true;error.value='';try{const manifest=JSON.parse(text.value);await post('/plugins',{manifest,enabled:false,consent:false,revision:0});text.value='';await load()}catch(e){error.value=e instanceof Error?e.message:'Manifest无效'}finally{busy.value=false}}
async function toggle(item:Plugin){try{if(!item.enabled)await ElMessageBox.confirm(`启用后会向 ${item.manifest.endpoint} 发送文件名、识别线索或整理后的相对路径与状态。插件不能获得密码、Cookie或播放密钥。是否授权？`,'授权外部扩展',{type:'warning',confirmButtonText:'授权并启用',cancelButtonText:'取消'});await post('/plugins',{manifest:item.manifest,enabled:!item.enabled,consent:true,revision:item.revision});await load()}catch(e){if(e instanceof Error)error.value=e.message}}
onMounted(load)
</script>
<template><section class="page-heading"><div><span class="page-kicker">SYSTEM / 扩展</span><h1>插件扩展</h1><p>版本化能力接口 · 内置识别/命名 · HTTPS Webhook 扩展，不下载或执行未知代码。</p></div><el-button @click="load">刷新插件</el-button></section><el-alert v-if="error" :title="error" type="error" :closable="false"/><section class="plugin-grid"><article v-for="item in items" :key="item.manifest.id" class="panel"><div class="panel-title"><h2>{{item.manifest.name}}</h2><el-tag>{{item.builtin?'内置':item.enabled?'已启用':'停用'}}</el-tag></div><p class="muted">{{item.manifest.id}} · {{item.manifest.version}} · 合约 v{{item.manifest.contractVersion}}</p><p>{{item.manifest.capabilities.join('、')}}</p><code v-if="item.manifest.endpoint">{{item.manifest.endpoint}}</code><el-button v-if="!item.builtin" @click="toggle(item)">{{item.enabled?'停用扩展':'授权并启用'}}</el-button></article></section><section class="panel"><h2>导入扩展 Manifest</h2><p class="field-hint">新扩展默认停用。能力仅支持 media.recognize、media.organized。地址必须HTTPS且不得指向私网、元数据服务或包含凭据。启用前需要单独授权数据传输。</p><el-input v-model="text" type="textarea" :rows="9" aria-label="插件Manifest" placeholder='{"id":"my-helper","name":"整理助手","version":"1.0.0","contractVersion":1,"endpoint":"https://your-domain.example/hook","capabilities":["media.organized"]}'/><el-button type="primary" :loading="busy" :disabled="!text.trim()" @click="add">导入为停用插件</el-button></section></template>
<style scoped>.plugin-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:20px;margin-bottom:24px}.plugin-grid p{margin:12px 0;line-height:1.7}.plugin-grid code{display:block;margin:14px 0;overflow-wrap:anywhere}.el-textarea{margin:16px 0}</style>
